# Alle datum-strings die we nodig hebben als set (YYYYMMDD)
ALLE_DATUMS = set()
DATUM_NAAR_FEESTDAG = {}  # YYYYMMDD → [(feestdag, jaar), ...]
for feestdag, jaren in FEESTDAGEN_DATUMS.items():
    for jaar, datum in jaren.items():
        d_str = datum.replace("-", "")
        ALLE_DATUMS.add(d_str)
        DATUM_NAAR_FEESTDAG.setdefault(d_str, []).append((feestdag, int(jaar)))


def parse_etmgeg(tekst):
    """Parst etmgeg tekstformaat → dict {YYYYMMDD: {TX, TN, TG, RH, SQ, FX}}
    In etmgeg-bestanden begint de headerregel met '# STN,' en heet
    de max. windstoot FXX (niet FX zoals in de daggegevens-API).
    """
    header = None
    resultaat = {}
    for regel in tekst.splitlines():
        regel = regel.strip()
        if not regel:
            continue
        # Headerregel: begint met '# STN,' of 'STN,'
        if regel.startswith("# STN") or (header is None and regel.startswith("STN")):
            header = [k.strip() for k in regel.lstrip("# ").split(",")]
            continue
        if header is None or regel.startswith("#"):
            continue
        velden = [v.strip() for v in regel.split(",")]
        if len(velden) < len(header):
            continue
        rij = dict(zip(header, velden))

        def getal(key):
            v = rij.get(key, "")
            if v == "":
                return None
            try:
                return int(v)
            except ValueError:
                return None

        yyyymmdd = rij.get("YYYYMMDD", "")
        if not yyyymmdd:
            continue
        resultaat[yyyymmdd] = {
            "TX": getal("TX"),
            "TN": getal("TN"),
            "TG": getal("TG"),
            "RH": getal("RH"),
            "SQ": getal("SQ"),
            "FX": getal("FXX"),  # etmgeg gebruikt FXX voor max. windstoot
        }
    return resultaat


def parse_epen_csv(bestand, csv_code):
    resultaat = {}
    try:
        import pandas as pd, io as _io
        with open(bestand, encoding="utf-8-sig") as f:
            raw = f.read()
        lines = raw.splitlines()
        cleaned = []
        for line in lines:
            line = line.strip()
            if line.startswith('"') and line.endswith('"'):
                line = line[1:-1]
            line = line.replace('""', '"')
            cleaned.append(line)
        joined = "\n".join(cleaned)
        df = pd.read_csv(_io.StringIO(joined))
        df = df[df["DS_CODE"] == csv_code].copy()
        for _, rij in df.iterrows():
            yyyymmdd = str(rij["IT_DATETIME"])[:8]
            def g(col):
                v = rij.get(col)
                try: return int(round(float(v) * 10))
                except: return None
            resultaat[yyyymmdd] = {"TX": g("REH1.TX"), "TN": g("REH1.TN"), "TG": g("REH1.TG"), "RH": g("REN1.RD"), "SQ": None, "FX": None}
    except Exception as e:
        print(f"  x CSV-fout ({csv_code}): {e}", file=sys.stderr)
    return resultaat


def parse_winterswijk_csv(bestand):
    resultaat = {}
    try:
        with open(bestand, encoding="latin-1") as f:
            lines = f.readlines()
        header = None
        for i, line in enumerate(lines):
            if line.strip().startswith("DATUM"):
                header = [c.strip() for c in line.strip().split(",")]
                data_lines = lines[i+1:]
                break
        if not header:
            return {}
        for line in data_lines:
            velden = [v.strip() for v in line.strip().split(",")]
            if len(velden) < len(header):
                continue
            rij = dict(zip(header, velden))
            if rij.get("tijd") != "2400":
                continue
            yyyymmdd = rij.get("DATUM", "")
            if not yyyymmdd:
                continue
            def g(key):
                v = rij.get(key, "")
                if v == "": return None
                try: return int(v)
                except: return None
            resultaat[yyyymmdd] = {"TX": g("TX"), "TN": g("TN"), "TG": None, "RH": g("RD"), "SQ": None, "FX": None}
    except Exception as e:
        print(f"  x Winterswijk CSV-fout: {e}", file=sys.stderr)
    return resultaat


def haal_station_data(stn_nr):
    """Haalt alle daggegevens op voor één station via etmgeg ZIP (cdn.knmi.nl)."""
    info = STATIONS.get(stn_nr, {})
    csv_bestand = info.get("csv")
    if csv_bestand:
        script_dir = os.path.dirname(os.path.abspath(__file__))
        pad = os.path.join(script_dir, csv_bestand)
        if not os.path.exists(pad):
            print(f"  ✗ CSV niet gevonden: {pad}", file=sys.stderr)
            return {}
        csv_type = info.get("csv_type", "")
        if csv_type == "winterswijk":
            return parse_winterswijk_csv(pad)
        elif csv_type == "epen":
            return parse_epen_csv(pad, info.get("csv_code", ""))
        return {}
    url = f"https://cdn.knmi.nl/knmi/map/page/klimatologie/gegevens/daggegevens/etmgeg_{stn_nr}.zip"
    try:
        r = requests.get(url, timeout=120)
        r.raise_for_status()
        with zipfile.ZipFile(io.BytesIO(r.content)) as z:
            naam = z.namelist()[0]
            tekst = z.read(naam).decode("latin-1")
        return parse_etmgeg(tekst)
    except Exception as e:
        print(f"  ✗ Fout bij {stn_nr}: {e}", file=sys.stderr)
        return {}


def verwerk_stations(station_nrs):
    """Verwerkt een lijst stationsnummers en retourneert feestdag-data."""
    output = {
        "gegenereerd": datetime.now().isoformat(),
        "stations": {},
        "data": {},
    }

    for nr in station_nrs:
        info = STATIONS.get(nr, {"naam": str(nr), "lat": 0, "lon": 0, "hoofd": False})
        naam = info["naam"]
        print(f"→ Station {nr} – {naam} …", flush=True)

        dag_data = haal_station_data(nr)
        if not dag_data:
            print(f"  (geen data)", flush=True)
            continue

        output["stations"][str(nr)] = {
            "naam": naam,
            "lat":  info["lat"],
            "lon":  info["lon"],
            "hoofd": info["hoofd"],
        }

        feestdag_rijen = {}
        for feestdag, jaren in FEESTDAGEN_DATUMS.items():
            rijen = []
            for jaar, datum in jaren.items():
                d_str = datum.replace("-", "")
                if d_str in dag_data:
                    d = dag_data[d_str]
                    rijen.append({
                        "jaar": int(jaar),
                        "datum": datum,
                        "TX":  d["TX"],
                        "TN":  d["TN"],
                        "TG":  d["TG"],
                        "RH":  d["RH"],
                        "SQ":  d["SQ"],
                        "FX":  d["FX"],
                    })
            if rijen:
                feestdag_rijen[feestdag] = rijen

        output["data"][str(nr)] = feestdag_rijen
        print(f"  ✓ {sum(len(v) for v in feestdag_rijen.values())} meetpunten", flush=True)

    return output


def main():
    script_dir = os.path.dirname(os.path.abspath(__file__))
    uitvoer_pad = os.path.join(script_dir, "feestdagen_data.json")

    # Kies stations: standaard alle, of --hoofd voor alleen hoofdstations
    if "--hoofd" in sys.argv:
        nrs = [nr for nr, info in STATIONS.items() if info["hoofd"]]
        print(f"Ophalen voor {len(nrs)} hoofdstations …")
    else:
        nrs = list(STATIONS.keys())
        print(f"Ophalen voor {len(nrs)} stations …")

    data = verwerk_stations(nrs)

    uitvoer_pad_js = uitvoer_pad.replace(".json", ".js")
    json_str = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
    with open(uitvoer_pad, "w", encoding="utf-8") as f:
        f.write(json_str)
    with open(uitvoer_pad_js, "w", encoding="utf-8") as f:
        f.write(f"const FEESTDAGEN_DATA = {json_str};")

    grootte_kb = os.path.getsize(uitvoer_pad_js) // 1024
    print(f"\n✓ Opgeslagen als {uitvoer_pad} en {uitvoer_pad_js} ({grootte_kb} KB)")


if __name__ == "__main__":
    main()
